import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0]); k = int(data[1])
    a = list(map(int, data[2:2 + n]))
    total = sum(1 for x in a if x == k)
    best = {}
    lastk = {}
    kc = 0
    gain = 0
    for x in a:
        if x == k:
            kc += 1
        else:
            if x in best:
                cur = max(best[x] - (kc - lastk[x]), 0) + 1
            else:
                cur = 1
            best[x] = cur
            lastk[x] = kc
            if cur > gain:
                gain = cur
    print(total + gain)

main()

